<section class="page-heading"><div><span class="eyebrow">PIPAS / ADMINISTRACIÓN</span><h1>Usuarios del sistema</h1><p>Gestiona el acceso del equipo al módulo Padrón.</p></div></section><?php if($error):?><div class="alert danger" role="alert"><?= e($error) ?></div><?php endif;?><div class="detail-grid"><section class="card"><div class="table-wrap"><table><thead><tr><th>Operador</th><th>Usuario</th><th>Perfil</th><th>Estado</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?= e($u['nombre']) ?></td><td><?= e($u['usuario']) ?></td><td><?= (int)$u['perfil']===1?'ROOT':'ALTAS' ?></td><td><?= $u['activo']?'Activo':'Inactivo' ?></td></tr><?php endforeach;?></tbody></table></div></section><section class="card form-section"><h2>Nuevo operador</h2><form method="post" class="stack-form"><?= csrf() ?><label>Nombre<input name="nombre" required maxlength="100" autocomplete="off" value="<?= e($_POST['nombre']??'') ?>"></label><label>Usuario<input name="usuario" required maxlength="60" minlength="3" pattern="[a-zA-Z0-9._-]+" autocomplete="off" value="<?= e($_POST['usuario']??'') ?>"></label><label>Perfil<select name="perfil"><option value="11">ALTAS · Consulta y edición</option><option value="1">ROOT · Administración completa</option></select></label><label>Contraseña inicial<input type="password" name="password" required minlength="12" maxlength="200" autocomplete="new-password"><small>Al menos 12 caracteres.</small></label><button class="button primary full">Crear usuario <?= icon('plus') ?></button></form></section></div>
